package ru.avrescue.app;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.location.*;
import android.media.Ringtone;
import android.media.RingtoneManager;
import android.net.Uri;
import android.os.*;
import org.json.*;

public class DriverLocationService extends Service implements LocationListener {
 public static final String ACTION_START="ru.avrescue.app.START_DRIVER_SERVICE";
 public static final String ACTION_STOP="ru.avrescue.app.STOP_DRIVER_SERVICE";
 public static final String ACTION_STOP_ALERT="ru.avrescue.app.STOP_ORDER_ALERT";
 private static final String CHANNEL_TRACKING="driver_tracking";
 private static final String CHANNEL_ORDERS="new_orders_v2";
 private static final long MAX_LOCATION_AGE_MS=120000;
 private static final float MAX_LOCATION_ACCURACY_M=250f;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private LocationManager locationManager;private volatile Location lastLocation;private volatile long lastHeartbeatElapsed=0;private String alertedOfferId="";private Ringtone ringtone;
 private final Runnable poll=new Runnable(){public void run(){if(!ApiClient.hasToken()){stopSelf();return;}pollOrders();handler.postDelayed(this,8000);}};

 public void onCreate(){super.onCreate();ApiClient.load(this);createChannels();hardenChannels();startForeground(4101,trackingNotification());startLocation();handler.post(poll);}
 public int onStartCommand(Intent intent,int flags,int startId){String action=intent==null?ACTION_START:intent.getAction();if(ACTION_STOP_ALERT.equals(action)){stopAlert();return START_STICKY;}if(ACTION_STOP.equals(action)){stopAlert();stopSelf();return START_NOT_STICKY;}return START_STICKY;}
 public android.os.IBinder onBind(Intent intent){return null;}

 private void createChannels(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel tracking=new NotificationChannel(CHANNEL_TRACKING,"Работа на линии",NotificationManager.IMPORTANCE_LOW);tracking.setSound(null,null);nm.createNotificationChannel(tracking);NotificationChannel orders=new NotificationChannel(CHANNEL_ORDERS,"Новые заказы",NotificationManager.IMPORTANCE_HIGH);orders.enableVibration(true);nm.createNotificationChannel(orders);}}
 private void hardenChannels(){if(Build.VERSION.SDK_INT>=26){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);for(String id:new String[]{CHANNEL_TRACKING,CHANNEL_ORDERS}){NotificationChannel c=nm.getNotificationChannel(id);if(c!=null){c.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);nm.createNotificationChannel(c);}}}}
 private Notification trackingNotification(){Intent open=new Intent(this,DashboardActivity.class).putExtra("open_line",true);PendingIntent pi=PendingIntent.getActivity(this,4101,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL_TRACKING):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle("AV Rescue — вы на линии").setContentText("Геопозиция и новые заказы обновляются в фоне").setOngoing(true).setContentIntent(pi).build();}
 private void startLocation(){locationManager=(LocationManager)getSystemService(LOCATION_SERVICE);if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return;}try{if(locationManager.isProviderEnabled(LocationManager.GPS_PROVIDER))locationManager.requestLocationUpdates(LocationManager.GPS_PROVIDER,10000,10,this);if(locationManager.isProviderEnabled(LocationManager.NETWORK_PROVIDER))locationManager.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,10000,10,this);Location gps=locationManager.getLastKnownLocation(LocationManager.GPS_PROVIDER),network=locationManager.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);Location x=bestFreshLocation(gps,network);if(x!=null)sendLocation(x);}catch(Exception ignored){}}
 public void onLocationChanged(Location location){if(isFreshLocation(location))sendLocation(location);}
 private boolean isFreshLocation(Location location){if(location==null||location.getTime()<=0||System.currentTimeMillis()-location.getTime()>MAX_LOCATION_AGE_MS)return false;return !location.hasAccuracy()||location.getAccuracy()<=MAX_LOCATION_ACCURACY_M;}
 private Location bestFreshLocation(Location a,Location b){boolean af=isFreshLocation(a),bf=isFreshLocation(b);if(!af)return bf?b:null;if(!bf)return a;if(Math.abs(a.getTime()-b.getTime())>30000)return a.getTime()>b.getTime()?a:b;if(a.hasAccuracy()&&b.hasAccuracy())return a.getAccuracy()<=b.getAccuracy()?a:b;return a.getTime()>=b.getTime()?a:b;}
 private void saveLocation(Location location){lastLocation=location;getSharedPreferences("avr",MODE_PRIVATE).edit().putLong("last_lat",Double.doubleToRawLongBits(location.getLatitude())).putLong("last_lng",Double.doubleToRawLongBits(location.getLongitude())).putLong("last_fix_time",location.getTime()).putFloat("last_accuracy",location.hasAccuracy()?location.getAccuracy():0).apply();}
 private Location cachedFreshLocation(){android.content.SharedPreferences p=getSharedPreferences("avr",MODE_PRIVATE);long a=p.getLong("last_lat",0),b=p.getLong("last_lng",0),time=p.getLong("last_fix_time",0);if(a==0||b==0||time<=0||System.currentTimeMillis()-time>MAX_LOCATION_AGE_MS)return null;Location x=new Location("cached");x.setLatitude(Double.longBitsToDouble(a));x.setLongitude(Double.longBitsToDouble(b));x.setTime(time);float accuracy=p.getFloat("last_accuracy",0);if(accuracy>0)x.setAccuracy(accuracy);return isFreshLocation(x)?x:null;}
 private void sendLocation(Location location){if(!isFreshLocation(location))return;saveLocation(location);lastHeartbeatElapsed=SystemClock.elapsedRealtime();new Thread(()->{try{ApiClient.post("/api/mobile_location.php",new JSONObject().put("lat",location.getLatitude()).put("lng",location.getLongitude()).put("accuracy_m",location.hasAccuracy()?location.getAccuracy():JSONObject.NULL).put("captured_at_ms",location.getTime()).put("online",true));}catch(Exception ignored){}}).start();}
 private void heartbeat() throws Exception{long now=SystemClock.elapsedRealtime();if(now-lastHeartbeatElapsed<30000)return;Location current=isFreshLocation(lastLocation)?lastLocation:cachedFreshLocation();if(current==null)return;lastHeartbeatElapsed=now;ApiClient.post("/api/mobile_location.php",new JSONObject().put("lat",current.getLatitude()).put("lng",current.getLongitude()).put("accuracy_m",current.hasAccuracy()?current.getAccuracy():JSONObject.NULL).put("captured_at_ms",current.getTime()).put("online",true));}
 private void pollOrders(){new Thread(()->{try{heartbeat();JSONObject r=ApiClient.get("/api/mobile_dashboard.php");JSONArray orders=r.optJSONArray("orders");JSONObject offer=null;if(orders!=null)for(int i=0;i<orders.length();i++){JSONObject o=orders.optJSONObject(i);if(o!=null&&"offered".equals(o.optString("status"))){offer=o;break;}}JSONArray partner=r.optJSONArray("partner_orders");JSONObject newPartner=null;if(partner!=null)for(int i=0;i<partner.length();i++){JSONObject o=partner.optJSONObject(i);if(o==null||!"available".equals(o.optString("status")))continue;String id=o.optString("id","");if(!id.isEmpty()&&!getSharedPreferences("avr",MODE_PRIVATE).getBoolean("partner_notified_"+id,false)){newPartner=o;break;}}final JSONObject current=offer,partnerOrder=newPartner;handler.post(()->{if(current==null){stopAlert();alertedOfferId="";}else if(!current.optString("id").equals(alertedOfferId)){alertedOfferId=current.optString("id");showOffer(current);}if(partnerOrder!=null)showPartnerOffer(partnerOrder);});}catch(Exception ignored){}}).start();}
 private void showOffer(JSONObject order){stopAlert();try{Uri sound=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);if(sound==null)sound=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION);ringtone=RingtoneManager.getRingtone(this,sound);if(Build.VERSION.SDK_INT>=28)ringtone.setLooping(true);ringtone.play();}catch(Exception ignored){}Intent open=new Intent(this,DashboardActivity.class).putExtra("open_line",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,order.optString("id").hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL_ORDERS):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Новый заказ AV Rescue").setContentText(order.optString("service")+" · "+order.optString("address")).setAutoCancel(true).setContentIntent(pi).setPriority(Notification.PRIORITY_MAX);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(order.optString("id").hashCode(),b.build());}
 private void showPartnerOffer(JSONObject order){String id=order.optString("id","");if(id.isEmpty())return;getSharedPreferences("avr",MODE_PRIVATE).edit().putBoolean("partner_notified_"+id,true).apply();Intent open=new Intent(this,DashboardActivity.class).putExtra("open_line",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,("partner-"+id).hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String route=order.optString("pickup_address","Координаты на карте");Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL_ORDERS):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Новая заявка партнёра").setContentText(order.optString("service","Эвакуация")+" · "+route).setStyle(new Notification.BigTextStyle().bigText("Точка А: "+route+"\nОткройте заявку, чтобы увидеть точку Б и детали.")).setAutoCancel(true).setContentIntent(pi).setPriority(Notification.PRIORITY_HIGH);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(("partner-"+id).hashCode(),b.build());}
 private void stopAlert(){try{if(ringtone!=null&&ringtone.isPlaying())ringtone.stop();}catch(Exception ignored){}ringtone=null;if(!alertedOfferId.isEmpty())try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(alertedOfferId.hashCode());}catch(Exception ignored){}}
 public void onProviderEnabled(String provider){}public void onProviderDisabled(String provider){}public void onStatusChanged(String provider,int status,Bundle extras){}
 public void onDestroy(){handler.removeCallbacks(poll);stopAlert();try{if(locationManager!=null)locationManager.removeUpdates(this);}catch(Exception ignored){}super.onDestroy();}
}
